const rows = $('Fetch Claims Ledger').all().map(i => i.json);
const cutoff = $today.minus({ days: 14 }).toFormat('yyyy-MM-dd');

const awaiting = rows.filter(r => r.status === 'validated' && String(r.service_date) <= cutoff);
const rejected = rows.filter(r => r.status === 'rejected');

if (!awaiting.length && !rejected.length) return [];

let awaitingTotal = 0;
for (const a of awaiting) { awaitingTotal += Number(a.total) || 0; }
awaitingTotal = Math.round(awaitingTotal * 100) / 100;

let html = '<h2>NDIS claims ageing report</h2>';

if (awaiting.length) {
  html += '<h3>' + awaiting.length + ' claims with no payment result after 14+ days ($' + awaitingTotal.toFixed(2) + ' outstanding)</h3>';
  html += '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Claim</th><th>Participant</th><th>Type</th><th>Service date</th><th>Amount</th></tr>';
  for (const a of awaiting) {
    html += '<tr><td>' + a.claim_reference + '</td><td>' + (a.participant_name || 'Unknown') + '</td><td>' + a.plan_type + '</td><td>' + a.service_date + '</td><td>$' + Number(a.total).toFixed(2) + '</td></tr>';
  }
  html += '</table><p>Agency claims: check the batch was uploaded to PRODA and process the results file. Plan/self-managed: chase the plan manager or participant for payment.</p>';
}

if (rejected.length) {
  html += '<h3>' + rejected.length + ' rejected claims awaiting resubmission</h3>';
  html += '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Claim</th><th>Participant</th><th>Reason</th></tr>';
  for (const r of rejected) {
    html += '<tr><td>' + r.claim_reference + '</td><td>' + (r.participant_name || 'Unknown') + '</td><td>' + (r.rejection_reason || '') + '</td></tr>';
  }
  html += '</table><p>Fix the cause and re-invoice in the PMS so these enter the next daily batch.</p>';
}

return [{ json: { html: html, awaiting_count: awaiting.length, rejected_count: rejected.length, awaiting_total: awaitingTotal.toFixed(2) } }];
